def comps8(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen and g[i][j]!=bg:
                col=g[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            if dy==0 and dx==0: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                                seen.add((ny,nx)); stack.append((ny,nx))
                out.append((col,cells))
    return out
